import threading, time

counter, lock = 0, threading.Lock()

def unsafe(n):
    global counter
    for _ in range(n):
        value = counter          # read
        time.sleep(0)            # a thread switch here (forced, to show the bug)
        counter = value + 1      # write: overwrites other threads' updates

def safe(n):
    global counter
    for _ in range(n):
        with lock:
            counter += 1

for fn in (unsafe, safe):
    counter = 0
    threads = [threading.Thread(target=fn, args=(2_000,)) for _ in range(4)]
    for t in threads: t.start()
    for t in threads: t.join()
    print(fn.__name__, counter)
# unsafe e.g. 2013   (lost updates; varies per run)
# safe 8000

import queue, threading

q: queue.Queue[int] = queue.Queue(maxsize=5)
results, lock = [], threading.Lock()

def worker():
    while True:
        try:
            n = q.get()
        except queue.ShutDown:        # 3.13+: queue shut down and empty
            return
        with lock:
            results.append(n * n)
        q.task_done()

workers = [threading.Thread(target=worker) for _ in range(3)]
for w in workers: w.start()
for n in range(10):
    q.put(n)                          # blocks while 5 items are waiting
q.join()                              # all items processed
q.shutdown()                          # wake workers so they exit
for w in workers: w.join()
print(sorted(results))                # [0, 1, 4, 9, 16, 25, 36, 49, 64, 81]

import time
from concurrent.futures import ThreadPoolExecutor, as_completed

def work(n):
    time.sleep(0.1 * (4 - n))          # later items finish first
    if n == 2:
        raise RuntimeError("task 2 broke")
    return n * 10

with ThreadPoolExecutor(max_workers=4) as pool:
    futures = {pool.submit(work, n): n for n in range(4)}
    for fut in as_completed(futures):
        n = futures[fut]
        try:
            print(f"task {n} -> {fut.result()}")
        except RuntimeError as e:
            print(f"task {n} failed: {e}")
# task 3 -> 30
# task 2 failed: task 2 broke
# task 1 -> 10
# task 0 -> 0

import time
from concurrent.futures import ProcessPoolExecutor

def count_primes(limit: int) -> int:
    return sum(all(n % d for d in range(2, int(n ** 0.5) + 1))
               for n in range(2, limit))

def run(executor_cls=None):
    jobs = [60_000] * 8
    t = time.perf_counter()
    if executor_cls is None:
        total = sum(map(count_primes, jobs))
    else:
        with executor_cls() as pool:
            total = sum(pool.map(count_primes, jobs))
    return total, round(time.perf_counter() - t, 2)

if __name__ == "__main__":             # required for spawn-based workers
    print("sequential", run())                    # e.g. (48464, 1.6)
    print("processes ", run(ProcessPoolExecutor)) # e.g. (48464, 0.45) on 4+ cores

import hashlib, sys, threading, time

print(sys.getswitchinterval())             # 0.005

data = b"x" * 50_000_000

def digest():
    hashlib.sha256(data).hexdigest()       # C code releases the GIL for large inputs

def py_loop():
    sum(range(10_000_000))                 # bytecode: holds the GIL

def timed(fn, n):
    t = time.perf_counter()
    threads = [threading.Thread(target=fn) for _ in range(n)]
    for th in threads: th.start()
    for th in threads: th.join()
    return time.perf_counter() - t

for fn in (digest, py_loop):
    print(fn.__name__, "4 threads vs 1:", round(timed(fn, 4) / timed(fn, 1), 1), "x")
# on a machine with 4+ free cores:
# digest 4 threads vs 1: ~1 x    -> runs in parallel (GIL released)
# py_loop 4 threads vs 1: ~4 x   -> serialised by the GIL
